/**
 * One step of a note edit, in the Quill delta shape: keep, insert or delete
 * characters, with formatting on kept or inserted text. Mirrors `DeltaOp`,
 * which has no `AbiType`.
 */
@Serializable(with = NoteChangeSerializer::class)
sealed class NoteChange {
    data class Retain(val value: NoteChange_Retain) : NoteChange()

    data class Insert(val value: NoteChange_Insert) : NoteChange()

    data class Delete(val value: NoteChange_Delete) : NoteChange()
}

internal object NoteChangeSerializer : KSerializer<NoteChange> {
    override val descriptor: SerialDescriptor = JsonElement.serializer().descriptor

    override fun serialize(encoder: Encoder, value: NoteChange) {
        val json = (encoder as JsonEncoder).json
        val element = when (value) {
            is NoteChange.Retain -> json.encodeToJsonElement(serializer<NoteChange_Retain>(), value.value)
            is NoteChange.Insert -> json.encodeToJsonElement(serializer<NoteChange_Insert>(), value.value)
            is NoteChange.Delete -> json.encodeToJsonElement(serializer<NoteChange_Delete>(), value.value)
        }
        encoder.encodeJsonElement(element)
    }

    override fun deserialize(decoder: Decoder): NoteChange {
        val json = (decoder as JsonDecoder).json
        val element = decoder.decodeJsonElement()
        runCatching { NoteChange.Retain(json.decodeFromJsonElement(serializer<NoteChange_Retain>(), element)) }.getOrNull()?.let { return it }
        runCatching { NoteChange.Insert(json.decodeFromJsonElement(serializer<NoteChange_Insert>(), element)) }.getOrNull()?.let { return it }
        runCatching { NoteChange.Delete(json.decodeFromJsonElement(serializer<NoteChange_Delete>(), element)) }.getOrNull()?.let { return it }
        throw SerializationException("No NoteChange variant matches " + element)
    }
}

@Serializable
data class NoteChange_Delete(
    val delete: UInt,
)

@Serializable
data class NoteChange_Insert(
    val insert: String,
    val attributes: Map<String, String>? = null,
)

@Serializable
data class NoteChange_Retain(
    val retain: UInt,
    val attributes: Map<String, String>? = null,
)

